4	export function generatePageHTML(page: ParsedPage, templateEngine?: TemplateEngine): string {
5	  if (templateEngine) {
6	    const templateName = page.frontmatter.template;
7	    const layoutName = page.frontmatter.layout;
8	    return templateEngine.renderPage(page, templateName, layoutName);
9	  }
10	
11	  return generatePageHTMLDefault(page);
12	}
13	
14	function generatePageHTMLDefault(page: ParsedPage): string {
15	  const { frontmatter, html, slug } = page;
16	  const date = frontmatter.date ? new Date(frontmatter.date).toLocaleDateString() : '';
17	  const tagsList = Array.isArray(frontmatter.tags) ? frontmatter.tags.join(', ') : '';
18	
19	  return `<!DOCTYPE html>
20	<html lang="en">
21	<head>
22	  <meta charset="UTF-8">
23	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
24	  <title>${escapeHtml(frontmatter.title)}</title>
25	  <style>
26	    body {
27	      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
28	      line-height: 1.6;
29	      max-width: 800px;
30	      margin: 0 auto;
31	      padding: 2rem;
32	      color: #333;
33	    }
34	    h1 { font-size: 2.5rem; margin-bottom: 0.5rem; }
35	    .meta { color: #666; font-size: 0.95rem; margin-bottom: 2rem; }
36	    .tag { display: inline-block; background: #e0e0e0; padding: 0.25rem 0.75rem; border-radius: 1rem; margin-right: 0.5rem; font-size: 0.9rem; }
37	    a { color: #0066cc; text-decoration: none; }
38	    a:hover { text-decoration: underline; }
39	    .nav { margin-bottom: 2rem; }
40	    .nav a { margin-right: 1rem; }
41	  </style>
42	</head>
43	<body>
44	  <div class="nav">
45	    <a href="index.html">← Back to index</a>
46	  </div>
47	  <article>
48	    <h1>${escapeHtml(frontmatter.title)}</h1>
49	    <div class="meta">
50	      ${date ? `<div>Published: ${date}</div>` : ''}
51	      ${tagsList ? `<div class="tags">${frontmatter.tags!.map((tag: string) => `<span class="tag">${escapeHtml(tag)}</span>`).join('')}</div>` : ''}
52	    </div>
53	    <div class="content">
54	      ${html}
55	    </div>
56	  </article>
57	</body>
58	</html>`;
59	}
60	
61	export function generateIndexHTML(pages: ParsedPage[]): string {
62	  const sortedPages = pages.sort((a, b) => {
63	    const dateA = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
64	    const dateB = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
65	    return dateB - dateA;
66	  });
67	
68	  const pageList = sortedPages
69	    .map(page => {
70	      const date = page.frontmatter.date ? new Date(page.frontmatter.date).toLocaleDateString() : 'No date';
71	      return `<li>
72	  <a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.frontmatter.title)}</a>
73	  <span class="date">${date}</span>
74	</li>`;
75	    })
76	    .join('\n');
77	
78	  return `<!DOCTYPE html>
79	<html lang="en">
80	<head>
81	  <meta charset="UTF-8">
82	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
83	  <title>Site Index</title>
84	  <style>
85	    body {
86	      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
87	      line-height: 1.6;
88	      max-width: 800px;
89	      margin: 0 auto;
90	      padding: 2rem;
91	      color: #333;
92	    }
93	    h1 { font-size: 2.5rem; margin-bottom: 2rem; }
94	    ul { list-style: none; padding: 0; }
95	    li {
96	      padding: 1rem 0;
97	      border-bottom: 1px solid #e0e0e0;
98	      display: flex;
99	      justify-content: space-between;
100	      align-items: center;
101	    }
102	    a { color: #0066cc; text-decoration: none; }
103	    a:hover { text-decoration: underline; }
104	    .date { color: #999; font-size: 0.9rem; }
105	  </style>
106	</head>
107	<body>
108	  <h1>Site Index</h1>
109	  <p>${pages.length} page${pages.length !== 1 ? 's' : ''} found</p>
110	  <ul>
111	${pageList}
112	  </ul>
113	</body>
114	</html>`;
115	}
116	
117	function escapeHtml(text: string): string {
118	  const map: { [key: string]: string } = {
119	    '&': '&amp;',
120	    '<': '&lt;',
121	    '>': '&gt;',
122	    '"': '&quot;',
123	    "'": '&#039;',
124	  };
125	  return text.replace(/[&<>"']/g, char => map[char]);
126	}
