1	import http from 'http';
2	import fs from 'fs';
3	import path from 'path';
4	import chokidar from 'chokidar';
5	import WebSocket from 'ws';
6	import { parseMarkdown } from './parser';
7	import { generatePageHTML, generateIndexHTML } from './generator';
8	import { TemplateEngine } from './template-engine';
9	
10	interface ServeOptions {
11	  content: string;
12	  output: string;
13	  templates?: string;
14	  port: number;
15	}
16	
17	const LIVE_RELOAD_SCRIPT = `
18	<script>
19	(function() {
20	  const port = parseInt(window.location.port) + 1;
21	  const ws = new WebSocket('ws://localhost:' + port);
22	  ws.addEventListener('message', (event) => {
23	    if (event.data === 'reload') {
24	      window.location.reload();
25	    }
26	  });
27	  ws.addEventListener('close', () => {
28	    setTimeout(() => window.location.reload(), 1000);
29	  });
30	})();
31	</script>
32	`;
33	
34	async function build(options: ServeOptions): Promise<void> {
35	  const { content: contentDir, output: outputDir, templates: templatesDir } = options;
36	
37	  if (!fs.existsSync(contentDir)) {
38	    console.error(`Error: Content directory "${contentDir}" does not exist`);
39	    return;
40	  }
41	
42	  if (!fs.existsSync(outputDir)) {
43	    fs.mkdirSync(outputDir, { recursive: true });
44	  }
45	
46	  let templateEngine: TemplateEngine | undefined;
47	  if (templatesDir && fs.existsSync(templatesDir)) {
48	    templateEngine = new TemplateEngine({ templateDir: templatesDir });
49	  }
50	
51	  const files = fs.readdirSync(contentDir).filter(file => file.endsWith('.md'));
52	
53	  if (files.length === 0) {
54	    console.warn(`Warning: No markdown files found in "${contentDir}"`);
55	  }
56	
57	  const pages = [];
58	
59	  for (const file of files) {
60	    const filePath = path.join(contentDir, file);
61	    const content = fs.readFileSync(filePath, 'utf-8');
62	    const slug = path.parse(file).name;
63	
64	    try {
65	      const page = await parseMarkdown(content, slug);
66	      pages.push(page);
67	
68	      const outputFile = path.join(outputDir, `${slug}.html`);
69	      const html = generatePageHTML(page, templateEngine);
70	      fs.writeFileSync(outputFile, html, 'utf-8');
71	      console.log(`✓ Rebuilt ${outputFile}`);
72	    } catch (error) {
73	      console.error(`Error processing ${file}:`, error);
74	    }
75	  }
76	
77	  const indexFile = path.join(outputDir, 'index.html');
78	  const indexHtml = generateIndexHTML(pages);
79	  fs.writeFileSync(indexFile, indexHtml, 'utf-8');
80	  console.log(`✓ Rebuilt ${indexFile}`);
81	}
82	
83	function injectLiveReloadScript(html: string): string {
84	  return html.replace('</body>', LIVE_RELOAD_SCRIPT + '</body>');
85	}
