87	export async function serve(options: ServeOptions): Promise<void> {
88	  console.log(`Starting dev server on http://localhost:${options.port}`);
89	  console.log(`WebSocket server on ws://localhost:${options.port + 1}`);
90	
91	  const server = http.createServer((req, res) => {
92	    const filePath = path.join(options.output, req.url === '/' ? 'index.html' : req.url);
93	    const normalizedPath = path.normalize(filePath);
94	
95	    if (!normalizedPath.startsWith(path.normalize(options.output))) {
96	      res.writeHead(403, { 'Content-Type': 'text/plain' });
97	      res.end('Forbidden');
98	      return;
99	    }
100	
101	    if (fs.existsSync(normalizedPath) && fs.statSync(normalizedPath).isFile()) {
102	      const content = fs.readFileSync(normalizedPath, 'utf-8');
103	      const contentType = normalizedPath.endsWith('.html') ? 'text/html' : 'application/octet-stream';
104	      let responseContent = content;
105	
106	      if (normalizedPath.endsWith('.html')) {
107	        responseContent = injectLiveReloadScript(content);
108	      }
109	
110	      res.writeHead(200, { 'Content-Type': contentType });
111	      res.end(responseContent);
112	    } else {
113	      res.writeHead(404, { 'Content-Type': 'text/plain' });
114	      res.end('Not Found');
115	    }
116	  });
117	
118	  const wss = new WebSocket.Server({ port: options.port + 1 });
119	
120	  let isBuilding = false;
121	
122	  async function rebuild(): Promise<void> {
123	    if (isBuilding) return;
124	    isBuilding = true;
125	    console.log('Detected changes, rebuilding...');
126	
127	    try {
128	      await build(options);
129	      console.log('Build complete!');
130	      wss.clients.forEach(client => {
131	        if (client.readyState === WebSocket.OPEN) {
132	          client.send('reload');
133	        }
134	      });
135	    } catch (error) {
136	      console.error('Build error:', error);
137	    } finally {
138	      isBuilding = false;
139	    }
140	  }
141	
142	  const watcher = chokidar.watch([options.content, ...(options.templates ? [options.templates] : [])], {
143	    ignored: /(^|[/\\])\./,
144	    persistent: true,
145	  });
146	
147	  watcher.on('change', () => rebuild());
148	  watcher.on('add', () => rebuild());
149	  watcher.on('unlink', () => rebuild());
150	
151	  server.listen(options.port, 'localhost', () => {
152	    console.log(`Dev server listening on http://localhost:${options.port}`);
153	    build(options).catch(error => console.error('Initial build failed:', error));
154	  });
155	
156	  wss.on('close', () => {
157	    watcher.close();
158	  });
159	}
